  get branchDailyClosingAuditSummary(): {
    rows: Array<{
      branch: SchoolBranchRecord;
      closingsCount: number;
      cashTotal: number;
      meezanTotal: number;
      hblTotal: number;
      digitalTotal: number;
      pettyTotal: number;
      billedTotal: number;
      collectedTotal: number;
      varianceTotal: number;
      pendingPrincipalCount: number;
      pendingOwnerCount: number;
      flaggedCount: number;
    }>;
    totals: {
      closingsCount: number;
      cashTotal: number;
      meezanTotal: number;
      hblTotal: number;
      digitalTotal: number;
      pettyTotal: number;
      billedTotal: number;
      collectedTotal: number;
      varianceTotal: number;
      pendingPrincipalCount: number;
      pendingOwnerCount: number;
      flaggedCount: number;
    };
  } {
    const branches = this.schoolBranchRecords || [];
    const reconciliations = this.feeReconciliations || [];
    const rows = branches.map(branch => {
      const list = reconciliations.filter(r => (r.branchId || branches[0]?.id) === branch.id);
      const cashTotal = list.reduce((s, r) => s + Number(r.counterCashReceived || 0), 0);
      const meezanTotal = list.reduce((s, r) => s + Number(r.bankDepositedMeezan || 0), 0);
      const hblTotal = list.reduce((s, r) => s + Number(r.bankDepositedHBL || 0), 0);
      const digitalTotal = list.reduce((s, r) => s + Number(r.onlineDigitalKuickPay || 0), 0);
      const pettyTotal = list.reduce((s, r) => s + Number(r.pettyExpenses || 0), 0);
      const billedTotal = list.reduce((s, r) => s + Number(r.totalSystemBilled || 0), 0);
      const collectedTotal = list.reduce((s, r) => s + Number(r.actualCollected || 0), 0);
      const varianceTotal = list.reduce((s, r) => s + Number(r.varianceAmount || 0), 0);
      const pendingPrincipalCount = list.filter(r => r.principalApprovalStatus === 'Pending Principal Review').length;
      const pendingOwnerCount = list.filter(r => r.ownerApprovalStatus === 'Pending Owner Review').length;
      const flaggedCount = list.filter(r => r.ownerApprovalStatus === 'Flagged by Owner' || r.principalApprovalStatus === 'Principal Flagged').length;
      return {
        branch,
        closingsCount: list.length,
        cashTotal,
        meezanTotal,
        hblTotal,
        digitalTotal,
        pettyTotal,
        billedTotal,
        collectedTotal,
        varianceTotal,
        pendingPrincipalCount,
        pendingOwnerCount,
        flaggedCount
      };
    });
    const totals = rows.reduce(
      (acc, r) => ({
        closingsCount: acc.closingsCount + r.closingsCount,
        cashTotal: acc.cashTotal + r.cashTotal,
        meezanTotal: acc.meezanTotal + r.meezanTotal,
        hblTotal: acc.hblTotal + r.hblTotal,
        digitalTotal: acc.digitalTotal + r.digitalTotal,
        pettyTotal: acc.pettyTotal + r.pettyTotal,
        billedTotal: acc.billedTotal + r.billedTotal,
        collectedTotal: acc.collectedTotal + r.collectedTotal,
        varianceTotal: acc.varianceTotal + r.varianceTotal,
        pendingPrincipalCount: acc.pendingPrincipalCount + r.pendingPrincipalCount,
        pendingOwnerCount: acc.pendingOwnerCount + r.pendingOwnerCount,
        flaggedCount: acc.flaggedCount + r.flaggedCount
      }),
      {
        closingsCount: 0,
        cashTotal: 0,
        meezanTotal: 0,
        hblTotal: 0,
        digitalTotal: 0,
        pettyTotal: 0,
        billedTotal: 0,
        collectedTotal: 0,
        varianceTotal: 0,
        pendingPrincipalCount: 0,
        pendingOwnerCount: 0,
        flaggedCount: 0
      }
    );
    return { rows, totals };
  }

  get branchComparisonRows(): Array<{
    branch: SchoolBranchRecord;
    wingsCount: number;
    studentsCount: number;
    facultyCount: number;
    staffCount: number;
    revenue: number;
    expenses: number;
    pendingDues: number;
    pendingClosings: number;
    netBalance: number;
    isSelected: boolean;
  }> {
    return (this.schoolBranchRecords || []).map(branch => {
      const wingsCount = (this.schoolWingRecords || []).filter(w => w.branchId === branch.id).length;
      const students = (this.activeStudents || []).filter(s => (s.branchId || 'BR-LHR-01') === branch.id);
      const faculty = (this.teachers || []).filter(t => (t.branchId || 'BR-LHR-01') === branch.id);
      const principals = (this.schoolPrincipals || []).filter(p => (p.branchId || 'BR-LHR-01') === branch.id);
      const staff = (this.schoolStaff || []).filter(sf => (sf.branchId || 'BR-LHR-01') === branch.id);
      const revenue = (this.finances || [])
        .filter(f => f.type === 'Income' && (f.branchId || 'BR-LHR-01') === branch.id)
        .reduce((acc, f) => acc + Number(f.amount || 0), 0);
      const financeExp = (this.finances || [])
        .filter(f => f.type === 'Expense' && (f.branchId || 'BR-LHR-01') === branch.id)
        .reduce((acc, f) => acc + Number(f.amount || 0), 0);
      const schoolExp = (this.schoolExpenses || [])
        .filter(e => (e.branchId || 'BR-LHR-01') === branch.id)
        .reduce((acc, e) => acc + Number(e.amount || 0), 0);
      const expenses = Math.max(financeExp, schoolExp);
      const pendingDues = students
        .filter(s => s.feeStatus !== 'Paid')
        .reduce((acc, s) => acc + Number(s.dueBakaya || s.feeAmount || 0), 0);
      const pendingClosings = (this.feeReconciliations || [])
        .filter(r => (r.branchId || 'BR-LHR-01') === branch.id && (!r.ownerApprovalStatus || r.ownerApprovalStatus === 'Pending Owner Review'))
        .length;

      return {
        branch,
        wingsCount,
        studentsCount: students.length,
        facultyCount: faculty.length,
        staffCount: principals.length + faculty.length + staff.length,
        revenue,
        expenses,
        pendingDues,
        pendingClosings,
        netBalance: revenue - expenses,
        isSelected: this.effectiveBranchScope === branch.id
      };
    });
  }

  get wingComparisonRows(): Array<{
    wing: SchoolWingRecord;
    branchName: string;
    studentsCount: number;
    facultyCount: number;
    revenue: number;
    pendingDues: number;
    isSelected: boolean;
  }> {
    const scope = this.effectiveBranchScope;
    const wings = scope === 'ALL' ? (this.schoolWingRecords || []) : this.getWingsForBranch(scope);
    return wings.map(wing => {
      const students = (this.activeStudents || []).filter(s => s.wingId === wing.id);
      const faculty = (this.teachers || []).filter(t => t.wingId === wing.id);
      const revenue = (this.finances || [])
        .filter(f => f.type === 'Income' && f.wingId === wing.id)
        .reduce((acc, f) => acc + Number(f.amount || 0), 0);
      const pendingDues = students
        .filter(s => s.feeStatus !== 'Paid')
        .reduce((acc, s) => acc + Number(s.dueBakaya || s.feeAmount || 0), 0);
      return {
        wing,
        branchName: this.resolveBranchName(wing.branchId),
        studentsCount: students.length,
        facultyCount: faculty.length,
        revenue,
        pendingDues,
        isSelected: this.effectiveWingScope === wing.id
      };
    });
  }

  setBranchScope(branchId: string): void {
    this.selectedBranchScope = branchId || 'ALL';
    if (this.selectedBranchScope !== 'ALL') {
      const wingValid = (this.schoolWingRecords || []).some(w => w.id === this.selectedWingScope && w.branchId === this.selectedBranchScope);
      if (!wingValid) this.selectedWingScope = 'ALL';
    }
    this.currentPage['students'] = 1;
    this.currentPage['finance'] = 1;
    this.saveStateToStorage();
    this.cdr.detectChanges();
  }

  setWingScope(wingId: string): void {
    this.selectedWingScope = wingId || 'ALL';
    this.currentPage['students'] = 1;
    this.currentPage['finance'] = 1;
    this.saveStateToStorage();
    this.cdr.detectChanges();
  }

  inspectBranch(branchId: string): void {
    if (this.selectedBranchScope === branchId && this.selectedWingScope === 'ALL') {
      this.setBranchScope('ALL');
      this.showToast('Showing Consolidated Group HQ (All Branches & Wings)', 'info');
      return;
    }
    this.setBranchScope(branchId);
    this.showToast(`Scoped dashboard to ${this.resolveBranchName(branchId)}`, 'success');
  }

  inspectWing(branchId: string, wingId: string): void {
    this.selectedBranchScope = branchId;
    this.selectedWingScope = wingId;
    this.currentPage['students'] = 1;
    this.saveStateToStorage();
    this.cdr.detectChanges();
    this.showToast(`Inspecting ${this.resolveWingName(wingId)} (${this.resolveBranchName(branchId)})`, 'success');
  }

