  async printBorrowSlip(): Promise<void> {
    const rec = this.selectedCirculationSlip;
    if (!rec) return;
    const html = buildBorrowSlipPrintHtml(
      {
        slipId: rec.issueNo || rec.id,
        bookTitle: rec.bookTitle,
        bookIsbn: rec.isbn || 'N/A',
        accessionCode: rec.bookId || rec.isbn,
        borrowerName: rec.borrowerName,
        borrowerRole: rec.borrowerType,
        borrowerId: rec.borrowerId,
        issueDate: rec.issueDate,
        dueDate: rec.dueDate,
        status: rec.status,
        fineAmount: Number(rec.fineAmount || 0),
        dailyFineRate: Number(this.dailyFineRatePKR || 50)
      },
      this.printBranding
    );
    const ok = await printHtmlInHiddenFrame(html);
    this.showToast(
      ok ? `Prepared branded Library Circulation Slip (${rec.issueNo || rec.id}).` : 'Print dialog unavailable in this view.',
      ok ? 'success' : 'warning'
    );
  }

  exportLibraryCirculationCSV(): void {
    if (!this.libraryCirculations.length) {
      this.showToast('No circulation records found to export', 'warning');
      return;
    }
    const headers = [
      'Sr No',
      'Issue Token Ref',
      'Book Title',
      'ISBN Number',
      'Borrower Full Name',
      'Borrower Roll / Staff ID',
      'Borrower Type',
      'Class / Department',
      'Issue Date',
      'Due Date',
      'Return Date',
      'Circulation Status',
      'Overdue Days',
      'Late Fine Accrued (PKR)',
      'Book Condition Remarks'
    ];
    const rows = this.libraryCirculations.map((c, i) => [
      i + 1,
      '"' + c.issueNo + '"',
      '"' + c.bookTitle + '"',
      '"' + c.isbn + '"',
      '"' + c.borrowerName + '"',
      '"' + c.borrowerId + '"',
      '"' + c.borrowerType + '"',
      '"' + c.gradeOrDept + '"',
      '"' + c.issueDate + '"',
      '"' + c.dueDate + '"',
      '"' + (c.returnDate || 'Pending') + '"',
      '"' + c.status + '"',
      c.overdueDays,
      c.fineAmount,
      '"' + (c.conditionNotes || 'N/A') + '"'
    ]);

    const csv = [headers.join(','), ...rows.map(r => r.join(','))].join('\n');
    const blob = new Blob([csv], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.setAttribute('download', 'Library_Circulation_Ledger_2026.csv');
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
    URL.revokeObjectURL(url);
    this.showToast('Library Circulation Ledger exported successfully (CSV)', 'success');
  }

