  async onAttendancePolicySaved(policy: OwnerAttendancePolicy): Promise<void> {
    this.ownerAttendancePolicy = this.mergeOwnerAttendancePolicy(policy);
    this.ownerBiometricPolicy = {
      ...this.ownerBiometricPolicy,
      principalBiometricAccessGranted: Boolean(this.ownerAttendancePolicy.roleAccess.principal.enabled),
      manualRollCallEnabled: !this.ownerAttendancePolicy.requireCameraForAllAttendance
    };
    this.syncPortalAttendanceTabAccess();
    this.saveStateToStorage();
    const isOnline = typeof navigator === 'undefined' || navigator.onLine !== false;
    const res = isOnline ? await this.backend.saveSchoolAttendancePolicy(this.ownerAttendancePolicy) : { ok: false };
    if (res?.ok && res.policy) {
      this.ownerAttendancePolicy = this.mergeOwnerAttendancePolicy(res.policy);
      this.ownerBiometricPolicy.principalBiometricAccessGranted = Boolean(this.ownerAttendancePolicy.roleAccess.principal.enabled);
      this.syncPortalAttendanceTabAccess();
      this.saveStateToStorage();
      this.showToast('School Owner Attendance Setup & Access Control saved & enforced across all portals.', 'success');
    } else {
      this.enqueueOfflineMutation('policy', this.ownerAttendancePolicy);
      this.showToast('Offline mode: Owner setup saved locally & queued to sync automatically when internet returns.', 'info');
    }
    this.cdr.detectChanges();
  }

  private resolveBiometricMemberScope(cat: AttendanceMemberCategory, memberId: string, gradeHint?: string, existing?: any) {
    const member = cat === 'student'
      ? (this.activeStudents || []).find(s => s.id === memberId)
      : cat === 'teacher'
        ? (this.teachers || []).find(t => t.id === memberId)
        : cat === 'principal'
          ? (this.schoolPrincipals || []).find(p => p.id === memberId)
          : (this.schoolStaff || []).find(sf => sf.id === memberId);
    const memberGradeHint = gradeHint
      || (member && 'grade' in member ? member.grade : undefined)
      || (member && 'assignedGrade' in member ? member.assignedGrade : undefined);
    return this.stampActiveBranchWing({
      ...existing,
      branchId: existing?.branchId || member?.branchId,
      branchName: existing?.branchName || member?.branchName,
      wingId: existing?.wingId || member?.wingId,
      wingName: existing?.wingName || member?.wingName
    }, memberGradeHint);
  }

  async onFaceProfileEnrolled(profile: FaceProfileRecord): Promise<void> {
    const scopedProfile: FaceProfileRecord = this.resolveBiometricMemberScope(
      profile.memberCategory,
      profile.memberId,
      profile.gradeOrDept,
      profile
    );
    const filtered = this.schoolFaceProfiles.filter(
      (fp) => !(fp.memberCategory === scopedProfile.memberCategory && fp.memberId === scopedProfile.memberId)
    );
    this.schoolFaceProfiles = [scopedProfile, ...filtered];
    this.syncBiometricFlagsFromFaceProfiles();
    this.saveStateToStorage();
    const isOnline = typeof navigator === 'undefined' || navigator.onLine !== false;
    const res = isOnline ? await this.backend.saveSchoolFaceProfile(scopedProfile) : { ok: false };
    if (!res?.ok) {
      this.enqueueOfflineMutation('face_profile', scopedProfile);
      this.showToast(`Offline mode: Face profile saved locally for ${scopedProfile.memberName} & queued for sync.`, 'info');
    } else {
      this.showToast(`Face profile enrolled & saved for ${scopedProfile.memberName} (${scopedProfile.memberCategory}).`, 'success');
    }
    this.cdr.detectChanges();
  }

  async onFaceProfileRemoved(profileId: string): Promise<void> {
    const removed = this.schoolFaceProfiles.find((fp) => fp.id === profileId);
    this.schoolFaceProfiles = this.schoolFaceProfiles.filter((fp) => fp.id !== profileId);
    if (removed) {
      if (removed.memberCategory === 'student') {
        this.activeStudents = this.activeStudents.map((s) => (s.id === removed.memberId ? { ...s, biometricEnrolled: false } : s));
      } else if (removed.memberCategory === 'teacher') {
        this.teachers = this.teachers.map((t) => (t.id === removed.memberId ? { ...t, biometricEnrolled: false } : t));
      } else if (removed.memberCategory === 'principal') {
        this.schoolPrincipals = this.schoolPrincipals.map((pr) => (pr.id === removed.memberId ? { ...pr, faceEnrolled: false } : pr));
      } else {
        this.schoolStaff = this.schoolStaff.map((sf) => (sf.id === removed.memberId ? { ...sf, faceEnrolled: false } : sf));
      }
    }
    this.saveStateToStorage();
    const isOnline = typeof navigator === 'undefined' || navigator.onLine !== false;
    const res = isOnline ? await this.backend.deleteSchoolFaceProfile(profileId) : { ok: false };
    if (!res?.ok) {
      this.enqueueOfflineMutation('face_delete', profileId);
    }
    this.showToast('Face biometric profile removed.', 'info');
    this.cdr.detectChanges();
  }

