  async onHubAttendanceRecorded(ev: {
    memberCategory: AttendanceMemberCategory;
    memberId: string;
    memberName: string;
    memberCode: string;
    gradeOrDept: string;
    status: 'Present' | 'Late' | 'Absent' | 'On Leave';
    punchType?: 'IN' | 'OUT';
    scheduledStartTime?: string;
    lateMinutes?: number;
    lateByLabel?: string;
    checkInTime?: string;
    verificationMode: string;
    confidenceScore: number;
    verifiedBy: string;
    snapshotData?: string;
  }): Promise<void> {
    const punch: 'IN' | 'OUT' = ev.punchType === 'OUT' ? 'OUT' : 'IN';
    const modeLower = String(ev.verificationMode || '').toLowerCase();
    const isBarcodeScan = modeLower.startsWith('barcode') || modeLower.startsWith('rfid');
    const isFingerprintScan = modeLower.startsWith('fingerprint') || modeLower.startsWith('biometric');
    const terminalGateName = `${isBarcodeScan ? 'Barcode / RFID Gate Kiosk' : (isFingerprintScan ? 'Biometric Fingerprint Terminal' : 'Camera Face Terminal')} · ${punch}`;
    const studentGateLabel = isBarcodeScan
      ? `Barcode / RFID Gate Kiosk (${punch})`
      : (isFingerprintScan
        ? `Biometric Fingerprint (${Math.round(ev.confidenceScore)}%)`
        : `Face Camera Terminal (${Math.round(ev.confidenceScore)}%)`);
    if (ev.memberCategory === 'student') {
      this.activeStudents = this.activeStudents.map((s) =>
        s.id === ev.memberId || s.rollNo === ev.memberCode
          ? { ...s, status: ev.status }
          : s
      );
      const nowTime = ev.checkInTime || new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });
      const todayLabel = new Date().toLocaleDateString('en-US', { day: '2-digit', month: 'short', year: 'numeric' });
      const dayLabel = new Date().toLocaleDateString('en-US', { weekday: 'long' });
      if (punch === 'OUT') {
        const existingIdx = this.studentAttendanceLog.findIndex((l) => l.date === todayLabel);
        if (existingIdx >= 0) {
          this.studentAttendanceLog = this.studentAttendanceLog.map((l, idx) =>
            idx === existingIdx ? { ...l, checkOut: nowTime } : l
          );
        }
      } else if (!this.studentAttendanceLog.some((l) => l.date === todayLabel)) {
        this.studentAttendanceLog = [
          {
            date: todayLabel,
            day: dayLabel,
            checkIn: nowTime,
            checkOut: 'Active',
            gate: studentGateLabel,
            status: ev.status
          },
          ...this.studentAttendanceLog
        ];
      }
    } else if (ev.memberCategory === 'teacher') {
      this.teachers = this.teachers.map((t) =>
        t.id === ev.memberId ? { ...t, attendanceStatus: ev.status } : t
      );
    } else if (ev.memberCategory === 'principal') {
      this.schoolPrincipals = this.schoolPrincipals.map((pr) =>
        pr.id === ev.memberId ? { ...pr, attendanceStatus: ev.status } : pr
      );
    } else {
      this.schoolStaff = this.schoolStaff.map((sf) =>
        sf.id === ev.memberId ? { ...sf, attendanceStatus: ev.status } : sf
      );
    }

    const nowTs = ev.checkInTime || new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', second: '2-digit' });
    const scheduledStart = ev.scheduledStartTime || this.ownerAttendancePolicy.scheduledStartTime || '08:00';
    const logEntry: FaceVerificationLogRecord = this.resolveBiometricMemberScope(
      ev.memberCategory,
      ev.memberId,
      ev.gradeOrDept,
      {
        id: `FLOG-${Date.now().toString(36).slice(-5)}`,
        memberCategory: ev.memberCategory,
        memberId: ev.memberId,
        memberName: ev.memberName,
        memberCode: ev.memberCode,
        gradeOrDept: ev.gradeOrDept,
        status: ev.status,
        punchType: punch,
        scheduledStartTime: scheduledStart,
        lateMinutes: ev.lateMinutes,
        lateByLabel: ev.lateByLabel,
        gateName: terminalGateName,
        verificationMode: ev.verificationMode,
        confidenceScore: ev.confidenceScore,
        verifiedBy: ev.verifiedBy,
        markedByRole: this.currentPortalRole || 'owner',
        date: new Date().toISOString().split('T')[0],
        timestamp: nowTs,
        snapshotData: ev.snapshotData
      }
    );
    this.faceVerificationLogs = [logEntry, ...this.faceVerificationLogs].slice(0, 80);

    this.recomputeAttendanceSummary();
    this.saveStateToStorage();

    const attendancePayload = {
      studentId: ev.memberId,
      studentName: ev.memberName,
      rollNo: ev.memberCode,
      grade: ev.gradeOrDept,
      status: ev.status,
      punchType: punch,
      checkInTime: ev.checkInTime || nowTs,
      scheduledStartTime: scheduledStart,
      lateMinutes: ev.lateMinutes,
      lateByLabel: ev.lateByLabel,
      gateName: terminalGateName,
      memberCategory: ev.memberCategory,
      verificationMode: ev.verificationMode,
      confidenceScore: ev.confidenceScore,
      verifiedBy: ev.verifiedBy,
      markedByRole: this.currentPortalRole || 'owner',
      branchId: logEntry.branchId,
      branchName: logEntry.branchName,
      wingId: logEntry.wingId,
      wingName: logEntry.wingName
    };

    const isOnline = typeof navigator === 'undefined' || navigator.onLine !== false;
    const punchLabel = punch === 'OUT' ? 'CHECKED OUT' : ev.status;

    if (!isOnline) {
      this.enqueueOfflineMutation('attendance', attendancePayload);
      this.showToast(
        `Offline saved (${ev.memberCategory.toUpperCase()}): ${ev.memberName} ${punchLabel} — auto-sync when online`,
        'info'
      );
      this.cdr.detectChanges();
      return;
    }

    this.cdr.detectChanges();
    void this.backend.saveSchoolAttendance(attendancePayload).then((res) => {
      if (!res?.ok) {
        this.enqueueOfflineMutation('attendance', attendancePayload);
        this.showToast(
          `Saved locally (${ev.memberCategory.toUpperCase()}): ${ev.memberName} ${punchLabel} — auto-sync queued`,
          'info'
        );
      }
      this.cdr.detectChanges();
    });
  }

  async onHubStaffCreated(payload: {
    name: string;
    fatherName?: string;
    cnic?: string;
    gender?: string;
    roleTitle: string;
    department: string;
    phone: string;
    shift: string;
    liteEnabled: boolean;
    customValues?: Record<string, string>;
  }): Promise<void> {
    const res = await this.backend.saveSchoolStaff(payload);
    const created: StaffMemberRecord = this.stampActiveBranchWing(res?.ok && res.staff
      ? res.staff
      : {
          id: `STF-${Date.now().toString(36).slice(-5).toUpperCase()}`,
          empCode: `STF-${Math.floor(200 + Math.random() * 799)}`,
          name: payload.name,
          fatherName: payload.fatherName || '',
          cnic: payload.cnic || '',
          gender: payload.gender || 'Male',
          nationality: 'Pakistani',
          roleTitle: payload.roleTitle,
          department: payload.department,
          phone: payload.phone,
          shift: payload.shift,
          status: 'ACTIVE',
          attendanceStatus: 'Absent',
          faceEnrolled: false,
          liteEnabled: payload.liteEnabled
        }, payload.department);
    this.schoolStaff = [created, ...this.schoolStaff];
    if (payload.customValues && Object.keys(payload.customValues).length > 0) {
      this.tableSchemaService.submitFormCustomInputs(
        'attendance_roster_staff',
        created.id,
        payload.customValues,
        { rowLabel: created.name }
      );
    }
    this.saveStateToStorage();
    this.showToast(`Campus staff member ${created.name} added (${created.empCode}). Enroll their face photo to activate gate scanning.`, 'success');
    this.cdr.detectChanges();
  }

  async onHubStaffDeleted(staffId: string): Promise<void> {
    this.schoolStaff = this.schoolStaff.filter((s) => s.id !== staffId);
    this.schoolFaceProfiles = this.schoolFaceProfiles.filter((fp) => !(fp.memberCategory === 'staff' && fp.memberId === staffId));
    this.schoolFingerprintProfiles = this.schoolFingerprintProfiles.filter((fp) => !(fp.memberCategory === 'staff' && fp.memberId === staffId));
    this.tableSchemaService.clearRowCustomData('attendance_roster_staff', [staffId]);
    this.saveStateToStorage();
    await this.backend.deleteSchoolStaff(staffId);
    this.showToast('Staff record removed from campus attendance roster.', 'info');
    this.cdr.detectChanges();
  }

