  async printPaySlip(): Promise<void> {
    const p = this.activePaySlipStaff;
    if (!p) return;
    const allow = Number(p.allowances || 0);
    const houseAllowance = Math.round(allow * 0.65);
    const medicalAllowance = Math.max(0, allow - houseAllowance);
    const html = buildSalarySlipHtml(
      {
        slipNo: p.id,
        payMonth: p.month || this.printBranding.salaryMonthLabel || 'October 2026',
        empCode: p.staffId,
        employeeName: p.staffName,
        designation: p.role,
        department: 'Campus Faculty & Staff',
        bankAccount: p.paymentMethod || 'Direct Bank Deposit',
        basicPay: Number(p.baseSalary || 0),
        houseAllowance,
        medicalAllowance,
        taxDeduction: Number(p.deductions || 0),
        advanceDeduction: 0,
        paymentMode: p.paymentMethod || this.printBranding.salaryPayModeLabel || 'Bank Transfer',
        statusLabel: p.status
      },
      this.printBranding
    );
    const ok = await printHtmlInHiddenFrame(html);
    this.showToast(
      ok ? `Prepared branded Salary Slip (${p.id}) for ${p.staffName}.` : 'Print dialog unavailable in this view.',
      ok ? 'success' : 'warning'
    );
  }

  exportBankSalaryAdviceCSV(selectedMonth?: string): void {
    const records = selectedMonth && selectedMonth !== 'All'
      ? this.staffPayrolls.filter(p => p.month === selectedMonth)
      : this.staffPayrolls;

    if (!records.length) {
      this.showToast('No payroll records found to export', 'warning');
      return;
    }

    const headers = [
      'Sr No',
      'Employee ID',
      'Staff Full Name',
      'Designation / Role',
      'Payroll Month',
      'Base Salary (PKR)',
      'Allowances (PKR)',
      'Deductions (PKR)',
      'Net Payable (PKR)',
      'Payment Status',
      'Payment Method',
      'Disbursed Date',
      'Bank Transfer Advice Ref'
    ];

    const rows = records.map((p, idx) => [
      idx + 1,
      '"' + (p.staffId || ('STF-' + (100 + idx))) + '"',
      '"' + p.staffName + '"',
      '"' + p.role + '"',
      '"' + p.month + '"',
      p.baseSalary,
      p.allowances,
      p.deductions,
      p.netPayable,
      '"' + p.status + '"',
      '"' + (p.paymentMethod || 'Bank Transfer') + '"',
      '"' + (p.disbursedDate || 'Pending') + '"',
      '"SC-SAL-' + (p.month ? p.month.replace(/[^a-zA-Z0-9]/g, '') : '2026') + '-' + (p.staffId || (idx + 1)) + '"'
    ]);

    const csvContent = [headers.join(','), ...rows.map(r => r.join(','))].join('\n');
    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    const filename = 'Bank_Salary_Advice_' + (selectedMonth || 'Batch').replace(/\s+/g, '_') + '_2026.csv';
    link.setAttribute('download', filename);
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
    URL.revokeObjectURL(url);

    this.showToast('Bank Salary Advice exported (' + records.length + ' records in Meezan/HBL corporate batch format)', 'success');
  }

